INSERT INTO `admin_notifications` VALUES (1,11,'critical_update','⚠️ Khóa học cần phê duyệt lại','Giảng viên Lê Thị Cê đã chỉnh sửa nội dung cốt lõi của khóa học \'Khởi nghiệp Kinh doanh Online từ A-Z\' (Bài học). Trạng thái khóa học đã tự động chuyển sang \'Chờ duyệt lại\'.','{\"change_log_id\":\"1\",\"entity_type\":\"lesson\",\"entity_id\":19,\"action_type\":\"create\",\"changed_fields\":[\"id\",\"chapter_id\",\"title\",\"content_type\",\"lesson_type\",\"content\",\"objectives\",\"ai_summary\",\"video_transcript\",\"lesson_context\",\"key_topics\",\"lesson_keywords\",\"video_url\",\"duration\",\"video_duration\",\"video_type\",\"video_filename\",\"video_path\",\"video_thumbnail\",\"video_size\",\"order_index\",\"is_free\",\"secure_token\",\"storage_driver\",\"created_at\",\"deleted_at\",\"deleted_by\",\"transcript_status\",\"verified_by_teacher\",\"verified_at\",\"strict_ai_mode\",\"teacher_notes\",\"enable_auto_summary\",\"enable_auto_keywords\",\"enable_auto_context\"],\"status_changed\":true}',1,'high','2026-05-26 06:10:27'),(2,11,'critical_update','⚠️ Thay đổi cốt lõi: Bài học','Giảng viên Lê Thị Cê đã chỉnh sửa nội dung cốt lõi (Bài học) trong khóa học \'Khởi nghiệp Kinh doanh Online từ A-Z\' (trạng thái hiện tại: pending_reapproval).','{\"change_log_id\":\"2\",\"entity_type\":\"lesson\",\"entity_id\":20,\"action_type\":\"create\",\"changed_fields\":[\"id\",\"chapter_id\",\"title\",\"content_type\",\"lesson_type\",\"content\",\"objectives\",\"ai_summary\",\"video_transcript\",\"lesson_context\",\"key_topics\",\"lesson_keywords\",\"video_url\",\"duration\",\"video_duration\",\"video_type\",\"video_filename\",\"video_path\",\"video_thumbnail\",\"video_size\",\"order_index\",\"is_free\",\"secure_token\",\"storage_driver\",\"created_at\",\"deleted_at\",\"deleted_by\",\"transcript_status\",\"verified_by_teacher\",\"verified_at\",\"strict_ai_mode\",\"teacher_notes\",\"enable_auto_summary\",\"enable_auto_keywords\",\"enable_auto_context\"],\"status_changed\":false}',1,'high','2026-05-26 06:10:30'),(3,11,'critical_update','⚠️ Thay đổi cốt lõi: Bài học','Giảng viên Lê Thị Cê đã chỉnh sửa nội dung cốt lõi (Bài học) trong khóa học \'Khởi nghiệp Kinh doanh Online từ A-Z\' (trạng thái hiện tại: pending_reapproval).','{\"change_log_id\":\"3\",\"entity_type\":\"lesson\",\"entity_id\":20,\"action_type\":\"delete\",\"changed_fields\":[\"id\",\"chapter_id\",\"title\",\"content_type\",\"lesson_type\",\"content\",\"objectives\",\"ai_summary\",\"video_transcript\",\"lesson_context\",\"key_topics\",\"lesson_keywords\",\"video_url\",\"duration\",\"video_duration\",\"video_type\",\"video_filename\",\"video_path\",\"video_thumbnail\",\"video_size\",\"order_index\",\"is_free\",\"secure_token\",\"storage_driver\",\"created_at\",\"deleted_at\",\"deleted_by\",\"transcript_status\",\"verified_by_teacher\",\"verified_at\",\"strict_ai_mode\",\"teacher_notes\",\"enable_auto_summary\",\"enable_auto_keywords\",\"enable_auto_context\"],\"status_changed\":false}',1,'high','2026-05-26 06:10:35'),(4,11,'non_critical_update','✏️ Cập nhật Bài học','Giảng viên Lê Thị Cê đã cập nhật Bài học trong khóa học \'Khởi nghiệp Kinh doanh Online từ A-Z\'.','{\"change_log_id\":\"4\",\"entity_type\":\"lesson\",\"entity_id\":19,\"action_type\":\"update\",\"changed_fields\":[\"ai_summary\",\"lesson_context\",\"key_topics\",\"lesson_keywords\"],\"status_changed\":false}',1,'low','2026-05-26 06:29:46'),(5,11,'critical_update','⚠️ Khóa học cần phê duyệt lại','Giảng viên Lê Thị Cê đã chỉnh sửa nội dung cốt lõi của khóa học \'Khởi nghiệp Kinh doanh Online\' (Thông tin khóa học). Trạng thái khóa học đã tự động chuyển sang \'Chờ duyệt lại\'.','{\"change_log_id\":\"5\",\"entity_type\":\"course\",\"entity_id\":11,\"action_type\":\"update\",\"changed_fields\":[\"title\"],\"status_changed\":true}',1,'high','2026-05-26 06:30:08'),(6,11,'critical_update','⚠️ Khóa học cần phê duyệt lại','Giảng viên Lê Thị Cê đã chỉnh sửa nội dung cốt lõi của khóa học \'Khởi nghiệp Kinh doanh Online\' (Bài