INSERT INTO `course_change_logs` VALUES (5,11,'course',11,'update','[\"title\"]','{\"title\":\"Kh\\u1edfi nghi\\u1ec7p Kinh doanh Online t\\u1eeb A-Z\",\"description\":\"Kh\\u00f3a h\\u1ecdc gi\\u00fap h\\u1ecdc vi\\u00ean hi\\u1ec3u c\\u00e1ch x\\u00e2y d\\u1ef1ng v\\u00e0 v\\u1eadn h\\u00e0nh m\\u1ed9t m\\u00f4 h\\u00ecnh kinh doanh online hi\\u1ec7n \\u0111\\u1ea1i t\\u1eeb con s\\u1ed1 0. H\\u1ecdc vi\\u00ean s\\u1ebd \\u0111\\u01b0\\u1ee3c h\\u01b0\\u1edbng d\\u1eabn t\\u1eeb nghi\\u00ean c\\u1ee9u th\\u1ecb tr\\u01b0\\u1eddng, x\\u00e2y d\\u1ef1ng th\\u01b0\\u01a1ng hi\\u1ec7u, marketing, b\\u00e1n h\\u00e0ng \\u0111\\u1ebfn t\\u1ed1i \\u01b0u l\\u1ee3i nhu\\u1eadn v\\u00e0 ch\\u0103m s\\u00f3c kh\\u00e1ch h\\u00e0ng.\",\"thumbnail\":\"\\/uploads\\/courses\\/2026_05\\/img_6a140090b3b26_1779695760.png\",\"price\":19000,\"is_premium\":1,\"category_id\":7,\"level\":\"beginner\",\"estimated_duration\":240,\"ai_course_summary\":\"Kh\\u00f3a h\\u1ecdc cung c\\u1ea5p ki\\u1ebfn th\\u1ee9c n\\u1ec1n t\\u1ea3ng v\\u1ec1 kinh doanh online, gi\\u00fap h\\u1ecdc vi\\u00ean bi\\u1ebft c\\u00e1ch t\\u00ecm s\\u1ea3n ph\\u1ea9m ti\\u1ec1m n\\u0103ng, x\\u00e2y d\\u1ef1ng th\\u01b0\\u01a1ng hi\\u1ec7u, tri\\u1ec3n khai marketing \\u0111a n\\u1ec1n t\\u1ea3ng v\\u00e0 t\\u1ed1i \\u01b0u doanh thu th\\u1ef1c t\\u1ebf.\",\"ai_keywords\":\"kinh doanh online, marketing, b\\u00e1n h\\u00e0ng, startup, th\\u01b0\\u01a1ng hi\\u1ec7u c\\u00e1 nh\\u00e2n, facebook ads, tiktok shop, ch\\u0103m s\\u00f3c kh\\u00e1ch h\\u00e0ng\",\"ai_focus\":\"Th\\u1ef1c h\\u00e0nh x\\u00e2y d\\u1ef1ng m\\u00f4 h\\u00ecnh kinh doanh th\\u1ef1c t\\u1ebf, t\\u01b0 duy b\\u00e1n h\\u00e0ng hi\\u1ec7n \\u0111\\u1ea1i, k\\u1ef9 n\\u0103ng marketing s\\u1ed1, ph\\u00e1t tri\\u1ec3n th\\u01b0\\u01a1ng hi\\u1ec7u v\\u00e0 t\\u1ed1i \\u01b0u doanh thu\"}','{\"title\":\"Kh\\u1edfi nghi\\u1ec7p Kinh doanh Online\",\"description\":\"Kh\\u00f3a h\\u1ecdc gi\\u00fap h\\u1ecdc vi\\u00ean hi\\u1ec3u c\\u00e1ch x\\u00e2y d\\u1ef1ng v\\u00e0 v\\u1eadn h\\u00e0nh m\\u1ed9t m\\u00f4 h\\u00ecnh kinh doanh online hi\\u1ec7n \\u0111\\u1ea1i t\\u1eeb con s\\u1ed1 0. H\\u1ecdc vi\\u00ean s\\u1ebd \\u0111\\u01b0\\u1ee3c h\\u01b0\\u1edbng d\\u1eabn t\\u1eeb nghi\\u00ean c\\u1ee9u th\\u1ecb tr\\u01b0\\u1eddng, x\\u00e2y d\\u1ef1ng th\\u01b0\\u01a1ng hi\\u1ec7u, marketing, b\\u00e1n h\\u00e0ng \\u0111\\u1ebfn t\\u1ed1i \\u01b0u l\\u1ee3i nhu\\u1eadn v\\u00e0 ch\\u0103m s\\u00f3c kh\\u00e1ch h\\u00e0ng.\",\"thumbnail\":\"\\/uploads\\/courses\\/2026_05\\/img_6a140090b3b26_1779695760.png\",\"price\":19000,\"is_premium\":1,\"category_id\":7,\"level\":\"beginner\",\"estimated_duration\":240,\"ai_course_summary\":\"Kh\\u00f3a h\\u1ecdc cung c\\u1ea5p ki\\u1ebfn th\\u1ee9c n\\u1ec1n t\\u1ea3ng v\\u1ec1 kinh doanh online, gi\\u00fap h\\u1ecdc vi\\u00ean bi\\u1ebft c\\u00e1ch t\\u00ecm s\\u1ea3n ph\\u1ea9m ti\\u1ec1m n\\u0103ng, x\\u00e2y d\\u1ef1ng th\\u01b0\\u01a1ng hi\\u1ec7u, tri\\u1ec3n khai marketing \\u0111a n\\u1ec1n t\\u1ea3ng v\\u00e0 t\\u1ed1i \\u01b0u doanh thu th\\u1ef1c t\\u1ebf.\",\"ai_keywords\":\"kinh doanh online, marketing, b\\u00e1n h\\u00e0ng, startup, th\\u01b0\\u01a1ng hi\\u1ec7u c\\u00e1 nh\\u00e2n, facebook ads, tiktok shop, ch\\u0103m s\\u00f3c kh\\u00e1ch h\\u00e0ng\",\"ai_focus\":\"Th\\u1ef1c h\\u00e0nh x\\u00e2y d\\u1ef1ng m\\u00f4 h\\u00ecnh kinh doanh th\\u1ef1c t\\u1ebf, t\\u01b0 duy b\\u00e1n h\\u00e0ng hi\\u1ec7n \\u0111\\u1ea1i, k\\u1ef9 n\\u0103ng marketing s\\u1ed1, ph\\u00e1t tri\\u1ec3n th\\u01b0\\u01a1ng hi\\u1ec7u v\\u00e0 t\\u1ed1i \\u01b0u doanh thu\"}',26,'2026-05-26 06:30:08'),(6,11,'lesson',21,'create','[\"id\",\"chapter_id\",\"title\",\"content_type\",\"lesson_type\",\"content\",\"objectives\",\"ai_summary\",\"video_transcript\",\"lesson_context\",\"key_topics\",\"lesson_keywords\",\"video_url\",\"duration\",\"video_duration\",\"video_type\",\"video_filename\",\"video_path\",\"video_thumbnail\",\"video_size\",\"order_index\",\"is_free\",\"secure_token\",\"storage_driver\",\"created_at\",\"deleted_at\",\"deleted_by\",\"transcript_status\",\"verified_by_teacher\",\"verified_at\",\"strict_ai_mode\",\"teacher_notes\",\"enable_auto_summary\",\"enable_auto_keywords\",\"enable_auto_context\"]',NULL,'{\"id\":21,\"chapter_id\":13,\"title\":\"TestVideo\",\"content_type\":\"video\",\"lesson_type\":\"video\",\"content\":\"<p>Video test<\\/p>\",\"objectives\":null,\"ai_summary\":\"### \\u0110i\\u1ec3m c\\u1ed1t l\\u00f5i b\\u00e0i h\\u1ecdc:\\n- **Kh\\u00e1i ni\\u1ec7m ch\\u00ednh**: Nghi\\u00ean c\\u1ee9u s\\u00e2u v\\u1ec1 TestVideo.\\n- **\\u1ee8ng d\\u1ee5ng**: C\\u00e1ch tri\\u1ec3n khai th\\u1ef1c ti\\u1ec5n trong c\\u00f4ng vi\\u1ec7c v\\u00e0 h\\u1ecdc t\\u1eadp.\\n- **L\\u01b0u \\u00fd quan tr\\u1ecdng**: \\u0110\\u1ecdc k\\u1ef9 t\\u00e0i li\\u1ec7u \\u0111\\u00ednh k\\u00e8m v\\u00e0 l\\u00e0m b\\u00e0i ki\\u1ec3m tra \\u0111\\u1ea7y \\u0111\\u1ee7.\",\"video_transcript\":\"[00:00] Xin ch\\u00e0o to\\u00e0n th\\u1ec3 h\\u1ecdc vi\\u00ean c\\u1ee7a AI Study Hub. Trong b\\u00e0i h\\u1ecdc \\\"TestVideo\\\" h\\u00f4m nay, ch\\u00fang ta s\\u1ebd c\\u00f9ng nghi\\u00ean c\\u1ee9u s\\u00e2u s\\u1eafc v\\u1ec1 c\\u00e1c kh\\u00e1i ni\\u1ec7m n\\u1ec1n t\\u1ea3ng c\\u1ee7a ch\\u1ee7 \\u0111\\u1ec1.\\n[02:00] \\u0110i s\\u00e2u v\\u00e0o ph\\u00e2n t\\u00edch ki\\u1ebfn tr\\u00fac th\\u1ef1c t\\u1ebf...\\n[05:00] T\\u00f3m l\\u01b0\\u1ee3c c\\u00e1c n\\u1ed9i dung c\\u1ed1t l\\u00f5i v\\u00e0 h\\u01b0\\u1edbng d\\u1eabn th\\u1ef1c h\\u00e0nh.\",\"lesson_context\":\"B\\u00e0i h\\u1ecdc n\\u00e0y n\\u1eb1m trong ch\\u01b0\\u01a1ng tr\\u00ecnh \\u0111\\u00e0o t\\u1ea1o chuy\\u00ean s\\u00e2u c\\u1ee7a kh\\u00f3a h\\u1ecdc, \\u0111\\u00f3ng vai tr\\u00f2 b\\u1ea3n l\\u1ec1 gi\\u00fap \\u0111\\u1ecbnh h\\u00ecnh t\\u01b0 duy thi\\u1ebft k\\u1ebf v\\u00e0 t\\u1ed1i \\u01b0u h\\u00f3a gi\\u1ea3i ph\\u00e1p c\\u00f4ng ngh\\u1ec7.\",\"key_topics\":\"ai study hub, testvideo\",\"lesson_keywords\":\"ai study hub, testvideo\",\"video_url\":\"\",\"duration\":0,\"video_duration\":0,\"video_type\":null,\"video_filename\":\"11\\/13\\/73626d7e5085a66170826e7280764565.mp4\",\"video_path\":null,\"video_thumbnail\":\"\\/uploads\\/courses\\/video_default_thumbnail.png\",\"video_size\":0,\"order_index\":3,\"is_free\":0,\"secure_token\":\"d1dddeff49f201c3fad8b69c58e2323833e0afa94ed57090cc35d31fc077f8cc\",\"storage_driver\":\"local\",\"created_at\":\"2026-05-31 04:34:36\",\"deleted_at\":null,\"deleted_by\":null,\"transcript_status\":\"auto_generated\",\"verified_by_teacher\":null,\"verified_at\":null,\"strict_ai_mode\":0,\"teacher_notes\":\"\",\"enable_auto_summary\":1,\"enable_auto_keywords\":1,\"enable_auto_context\":1}',26,'2026-05-31 04:34:36');
